-- Night Train Dispatch: project-owned boarding state, theme and authored geometry.
local Game = {}
local harbor = 0
local summit = 0
local heldHarbor = false
local heldSummit = false
local kit: UiComponentKit? = nil

local theme: UiComponentsTheme = {
    text={font_size=2,color={0.86,0.91,1,1},text_align="start",vertical_align="middle"},
    button={font_size=2,font_weight=700,color={0.08,0.12,0.2,1},background={0.98,0.73,0.25,1},border_radius=0.5,padding={left=1,right=1}},
    panel={background={0.09,0.16,0.27,1},border_color={0.24,0.36,0.53,1},border_width=0.15,border_radius=0.8},
}

-- The same generic factory serves two independent services through the official kit.
local function serviceCard(ui: UiComponentKit, id: string, y: number, title: string, route: string, value: number, action: string): UiComponentNode
    return ui.component({
        id=id,component="dispatch.service_card",rect={x=8,y=y,width=84,height=25},surface={kind="panel"},
        children={
            ui.text({id=ui.id(id,"title"),text=title,rect={x=11,y=y+16,width=32,height=5},style={font_size=3.1,font_weight=700}}),
            ui.text({id=ui.id(id,"route"),text=route,rect={x=11,y=y+10,width=32,height=4},style={font_size=1.8,color={0.57,0.7,0.86,1}}}),
            ui.text({id=ui.id(id,"status"),text="BOARDING NOW",rect={x=11,y=y+4,width=32,height=4},style={font_size=1.5,color={0.62,0.86,0.77,1},letter_spacing=0.12}}),
            ui.text({id=ui.id(id,"count"),text=tostring(value),rect={x=49,y=y+12,width=12,height=9},style={font_size=6.3,font_weight=700,text_align="center"}}),
            ui.text({id=ui.id(id,"unit"),text="ON BOARD",rect={x=47,y=y+6,width=16,height=4},style={font_size=1.4,text_align="center",color={0.57,0.7,0.86,1}}}),
            ui.button({id=ui.id(id,"board"),text="Admit passenger  +",action=action,rect={x=67,y=y+8,width=21,height=8}}),
        },
    })
end

local function present(api: EngineApi)
    local ui=kit
    assert(ui ~= nil)
    api.ui.setRoot({kind="screen",id="dispatch",node="boarding",children={
        ui.panel({id="dispatch/background",rect={x=0,y=0,width=100,height=100},background_for={screen=true},style={background={0.035,0.065,0.12,1}}}),
        ui.text({id="dispatch/kicker",text="CENTRAL STATION  /  NIGHT SHIFT",rect={x=8,y=93,width=84,height=4},style={font_size=1.5,letter_spacing=0.18,color={0.98,0.73,0.25,1}}}),
        ui.text({id="dispatch/title",text="Last departures",rect={x=8,y=83,width=84,height=8},style={font_size=5,font_weight=700}}),
        ui.text({id="dispatch/subtitle",text="Two platforms. Keep every boarding count on track.",rect={x=8,y=76,width=84,height=4},style={font_size=1.9,color={0.57,0.7,0.86,1}}}),
        serviceCard(ui,"dispatch/harbor",48,"Harbor Local","23:10  /  PLATFORM 04",harbor,"BoardHarbor"),
        serviceCard(ui,"dispatch/summit",18,"Summit Sleeper","23:40  /  PLATFORM 07",summit,"BoardSummit"),
        ui.text({id="dispatch/footer",text="Dispatcher log   /   Counts remain separate for each service.",rect={x=8,y=8,width=84,height=4},style={font_size=1.6,color={0.57,0.7,0.86,1}}}),
    }})
    api.observation.set("rail_counters",{harbor=harbor,summit=summit})
end

function Game.start(api: EngineApi)
    harbor=0
    summit=0
    heldHarbor=false
    heldSummit=false
    kit=api.ui.components.create(theme)
    local info=api.ui.components.info()
    api.observation.set("ui_package",{name=info.name,version=info.version,declared=info.declared})
    present(api)
end

function Game.update(api: EngineApi, _dt: number)
    local downHarbor=api.input.isDown("BoardHarbor")
    local downSummit=api.input.isDown("BoardSummit")
    if downHarbor and not heldHarbor then harbor += 1 end
    if downSummit and not heldSummit then summit += 1 end
    heldHarbor=downHarbor
    heldSummit=downSummit
    present(api)
end

return Game
